def _downtown() -> dict[str, tuple[float, float]]:
    """시마다 '동' 지역(읍·면 아닌 시내)의 평균 좌표. 주소의 법정동('신소현동')이 행정동 표에
    없을 때 시 전체 중심보다 낫다."""
    out = {}
    for city, places in DONG.items():
        pts = [xy for name, xy in places.items() if name.endswith("동")]
        if pts:
            out[city] = (round(sum(p[0] for p in pts) / len(pts), 4),
                         round(sum(p[1] for p in pts) / len(pts), 4))
    return out


DOWNTOWN = _downtown()
